import json
import sqlite3
from typing import Optional

from fastapi import FastAPI, Depends, HTTPException
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

# Database (in-memory sqlite3 so no files are written)
conn = sqlite3.connect(':memory:', check_same_thread=False)
conn.row_factory = sqlite3.Row
conn.execute(
    '''CREATE TABLE todos (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title VARCHAR(200) NOT NULL,
        description VARCHAR(500) DEFAULT '',
        is_done BOOLEAN DEFAULT 0,
        priority INTEGER DEFAULT 1
    )'''
)
conn.commit()


class TodoCreate(BaseModel):
    title: str = Field(..., min_length=1)
    description: str = ''
    priority: int = Field(default=1, ge=1, le=5)


class TodoUpdate(BaseModel):
    title: Optional[str] = Field(default=None, min_length=1)
    description: Optional[str] = None
    is_done: Optional[bool] = None
    priority: Optional[int] = Field(default=None, ge=1, le=5)


class TodoResponse(BaseModel):
    id: int
    title: str
    is_done: bool
    description: str
    priority: int


app = FastAPI()


def get_db():
    yield conn


def to_todo(row):
    d = dict(row)
    d['is_done'] = bool(d['is_done'])
    return d


def fetch(db, todo_id):
    row = db.execute('SELECT * FROM todos WHERE id = ?', (todo_id,)).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail='Todo not found')
    return row


@app.post('/todos/', response_model=TodoResponse, status_code=201)
def create_todo(todo: TodoCreate, db=Depends(get_db)):
    cur = db.execute(
        'INSERT INTO todos (title, description, is_done, priority) VALUES (?, ?, 0, ?)',
        (todo.title, todo.description, todo.priority),
    )
    db.commit()
    return to_todo(fetch(db, cur.lastrowid))


@app.get('/todos/', response_model=list[TodoResponse])
def list_todos(db=Depends(get_db)):
    return [to_todo(r) for r in db.execute('SELECT * FROM todos ORDER BY id')]


# Declared before /todos/{todo_id} so "pending" is not parsed as an id
@app.get('/todos/pending', response_model=list[TodoResponse])
def pending_todos(db=Depends(get_db)):
    rows = db.execute('SELECT * FROM todos WHERE is_done = 0 ORDER BY priority, id')
    return [to_todo(r) for r in rows]


@app.get('/todos/{todo_id}', response_model=TodoResponse)
def get_todo(todo_id: int, db=Depends(get_db)):
    return to_todo(fetch(db, todo_id))


@app.put('/todos/{todo_id}', response_model=TodoResponse)
def update_todo(todo_id: int, data: TodoUpdate, db=Depends(get_db)):
    fetch(db, todo_id)
    changes = data.model_dump(exclude_unset=True)
    for key, value in changes.items():
        db.execute(f'UPDATE todos SET {key} = ? WHERE id = ?', (value, todo_id))
    db.commit()
    return to_todo(fetch(db, todo_id))


@app.delete('/todos/{todo_id}', status_code=204)
def delete_todo(todo_id: int, db=Depends(get_db)):
    fetch(db, todo_id)
    db.execute('DELETE FROM todos WHERE id = ?', (todo_id,))
    db.commit()


def preview(todo, n):
    """Show the first n fields of a todo, then an ellipsis."""
    parts = [f'{json.dumps(k)}: {json.dumps(v)}' for k, v in list(todo.items())[:n]]
    return '{' + ', '.join(parts) + ', ...}'


client = TestClient(app)

resp = client.post('/todos/', json={'title': 'Learn FastAPI', 'description': 'Build a CRUD API', 'priority': 2})
print('POST /todos/ →', preview(resp.json(), 2))

resp = client.get('/todos/pending')
print('GET /todos/pending →', '[' + ', '.join(preview(t, 3) for t in resp.json()) + ']')
